import asyncio
async def safe(**kw):
    try:
        return await call_boto3(**kw)
    except Exception as e:
        return {"error": str(e)}

res = await asyncio.gather(
    safe(service_name="ec2", operation_name="DescribeRegions", region_name="us-east-1"),
    safe(service_name="ecs", operation_name="ListClusters", region_name="us-east-1"),
    safe(service_name="ec2", operation_name="DescribeVpcs", region_name="us-east-1"),
    safe(service_name="apprunner", operation_name="ListServices", region_name="us-east-1"),
    safe(service_name="rds", operation_name="DescribeDBInstances", region_name="us-east-1"),
    safe(service_name="lightsail", operation_name="GetInstances", region_name="us-east-1"),
    return_exceptions=True,
)
result = {"regions": res[0], "ecs": res[1], "vpcs": res[2], "apprunner": res[3], "rds": res[4], "lightsail": res[5]}
result

import asyncio, json
R="us-east-1"
async def c(s,o,p=None,r=R):
    return await call_boto3(service_name=s, operation_name=o, region_name=r, params=p or {})
async def safe(s,o,p=None,r=R):
    try: return await c(s,o,p,r)
    except Exception as e: return {"error": str(e)}

vpcs = await c("ec2","DescribeVpcs",{"Filters":[{"Name":"isDefault","Values":["true"]}]})
vpc = vpcs["Vpcs"][0]["VpcId"]
subs = await c("ec2","DescribeSubnets",{"Filters":[{"Name":"vpc-id","Values":[vpc]}]})
subnets = [{"id":s["SubnetId"],"az":s["AvailabilityZone"],"public":s.get("MapPublicIpOnLaunch")} for s in subs["Subnets"]]
result = {"vpc":vpc,"subnets":subnets}
result

